// === L?: function showUpgradeModal ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=1157c, shared=1157c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function showUpgradeModal(reason){
  const modal = document.getElementById('upgradeModal');
  const reasonEl = document.getElementById('upgradeReason');
  if (reasonEl){
    if (reason){ reasonEl.textContent = reason; reasonEl.style.display = 'block'; }
    else { reasonEl.textContent = ''; reasonEl.style.display = 'none'; }
  }
  // Fill payment info từ constants
  const g = id => document.getElementById(id);
  if (g('payBankName')) g('payBankName').textContent = PAYMENT_INFO.bank.name;
  if (g('payBankNum'))  g('payBankNum').textContent  = PAYMENT_INFO.bank.accountNumber;
  if (g('payBankOwner'))g('payBankOwner').textContent= PAYMENT_INFO.bank.owner;
  if (g('payZalo'))     g('payZalo').textContent     = PAYMENT_INFO.contact.zalo;
  if (g('payEmail'))    g('payEmail').textContent    = PAYMENT_INFO.contact.email;
  // Ẩn khung thanh toán tới khi chọn gói + dừng theo dõi cũ
  _upgStopWatch(); _upgOrderId = null;
  if (g('upgPay')) g('upgPay').style.display = 'none';
  if (g('upgPayMain')) g('upgPayMain').style.display = 'block';
  if (g('upgPayOk')) g('upgPayOk').style.display = 'none';
  modal.style.display = 'flex';
}

// === L?: let _upgOrderId, _upgPollTimer, _upgCountTimer ===
let _upgOrderId = null, _upgPollTimer = null, _upgCountTimer = null;

// === L?: function upgSelect ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở tool-upg.js (peer=3049c, shared=3049c). Peer load SAU → ghi đè bản này. Sửa ở peer.
async function upgSelect(plan){
  if (plan === 'free'){ closeUpgradeModal(); return; }
  const p = PRICING[plan];
  if (!p) return;
  const g = id => document.getElementById(id);
  const uid = window.currentUser?.uid || '';
  if (!uid){ showGate('Bạn cần đăng nhập trước khi thanh toán.', { upgrade: false }); return; }
  _upgStopWatch();
  // Reset về màn chờ
  if (g('upgPayMain')) g('upgPayMain').style.display = 'block';
  if (g('upgPayOk')) g('upgPayOk').style.display = 'none';
  const status = g('upgPayStatus');
  if (status) status.innerHTML = '<span class="upg-spin"></span><span>Hệ thống đang tự động kiểm tra…</span><b id="upgCountdown">10:00</b>';
  const amt = p.priceVND.toLocaleString('vi-VN') + 'đ';
  if (g('upgPayPlan')) g('upgPayPlan').textContent = p.label;
  if (g('upgPayAmount')) g('upgPayAmount').textContent = amt;
  if (g('upgPayAmount2')) g('upgPayAmount2').textContent = amt;
  // Mã đơn duy nhất — nội dung chuyển khoản
  const orderId = 'DH' + String(Math.floor(Math.random() * 1e8)).padStart(8, '0');
  _upgOrderId = orderId;
  if (g('upgOrderCode')) g('upgOrderCode').textContent = orderId;
  // Lưu đơn 'pending' lên Firestore để webhook đối soát
  const order = { orderId, uid, plan, amount: p.priceVND, status: 'pending',
                  createdAt: Date.now(), expiresAt: Date.now() + 10 * 60 * 1000,
                  email: window.currentUser?.email || '' };
  try { if (window.firebaseCreateOrder) await window.firebaseCreateOrder(orderId, order); }
  catch (e) { console.warn('Tạo đơn lỗi (kiểm tra Firestore Rules cho orders):', e); }
  // QR VietQR: nội dung CK = mã đơn
  const b = PAYMENT_INFO.bank;
  const qr = g('upgQr');
  if (qr){
    if (b.bankCode){
      qr.style.display = 'block';
      qr.src = `https://img.vietqr.io/image/${encodeURIComponent(b.bankCode)}-${encodeURIComponent(b.accountNumber)}-compact2.png`
             + `?amount=${p.priceVND}&addInfo=${encodeURIComponent(orderId)}&accountName=${encodeURIComponent(b.owner)}`;
    } else { qr.style.display = 'none'; }
  }
  const pay = g('upgPay');
  if (pay){ pay.style.display = 'block'; pay.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); }
  // Đếm ngược 10 phút
  let left = 10 * 60;
  const tick = () => {
    const el = document.getElementById('upgCountdown');
    if (el) el.textContent = String(Math.floor(left / 60)).padStart(2, '0') + ':' + String(left % 60).padStart(2, '0');
    if (left <= 0){ _upgStopWatch(); const st = document.getElementById('upgPayStatus'); if (st) st.innerHTML = '<span style="color:var(--red)">Đơn đã hết hạn — bấm lại gói để tạo mã mới.</span>'; }
    left--;
  };
  tick(); _upgCountTimer = setInterval(tick, 1000);
  // Poll trạng thái đơn mỗi 3s
  _upgPollTimer = setInterval(async () => {
    if (!_upgOrderId || !window.firebaseGetOrder) return;
    let od; try { od = await window.firebaseGetOrder(_upgOrderId); } catch (e) { return; }
    if (od && od.status === 'paid'){ _upgStopWatch(); await _upgOnPaid(p); }
  }, 3000);
}

// === L?: function _upgStopWatch ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=185c, shared=185c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function _upgStopWatch(){
  if (_upgPollTimer){ clearInterval(_upgPollTimer); _upgPollTimer = null; }
  if (_upgCountTimer){ clearInterval(_upgCountTimer); _upgCountTimer = null; }
}

// === L?: function _upgOnPaid ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=348c, shared=348c). Peer load SAU → ghi đè bản này. Sửa ở peer.
async function _upgOnPaid(p){
  await refreshTierFromCloud();
  const g = id => document.getElementById(id);
  if (g('upgPayMain')) g('upgPayMain').style.display = 'none';
  if (g('upgPayOk')) g('upgPayOk').style.display = 'block';
  const sub = g('upgPayOkSub'); if (sub) sub.textContent = 'Tài khoản đã lên gói ' + (p?.label || '') + '.';
}

// === L?: function refreshTierFromCloud ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở tool-ref.js (peer=519c, shared=519c). Peer load SAU → ghi đè bản này. Sửa ở peer.
async function refreshTierFromCloud(){
  try {
    if (!window.currentUser || !window.firebaseLoadDoc) return;
    const data = await window.firebaseLoadDoc(window.currentUser.uid);
    state.userTier = (data && data.tier) || 'free';
    state.proUntil = (data && data.proUntil) || null;
    if ((state.userTier === 'pro' || state.userTier === 'max') && state.proUntil && Date.now() > state.proUntil) state.userTier = 'free';
    if (typeof renderTierBadge === 'function') renderTierBadge();
  } catch (e) {}
}

