// === L?: function _upShrink ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=662c, shared=662c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function _upShrink(dataUrl, max){
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        const s = Math.min(1, max / Math.max(img.width, img.height));
        const w = Math.max(1, Math.round(img.width * s)), h = Math.max(1, Math.round(img.height * s));
        const cv = document.createElement('canvas'); cv.width = w; cv.height = h;
        cv.getContext('2d').drawImage(img, 0, 0, w, h);
        resolve({ url: cv.toDataURL('image/jpeg', 0.72), w: img.width, h: img.height });
      } catch(e){ resolve(null); }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  });
}

