    const row = tvResults.find(x => x.id === it.id); if (!row) return;
    row.status = 'gen'; row.pct = 6; tvRenderVideos();
    novaLog('🎬 ' + it.name + ' · gửi prompt: "' + _logClip(it.prompt) + '" → Veo đang dựng…', 'acc');
