  novaLog('▶ Bắt đầu tạo ' + targets.length + ' ảnh', 'acc');
  novaLog('  • Tài khoản: ' + (st.accountCount || 1) + ' · Luồng song song: ' + conc + (cfg.upscale && cfg.upscale !== '1' ? ' · Nâng nét: ' + cfg.upscale : ''), 'acc');
