    if (typeof novaLog === 'function'){ novaLog('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━', 'acc'); novaLog('▶ Tạo ' + units.length + ' ẢNH CẢNH' + (multi ? ' · ' + st.accountCount + ' tài khoản' : '') + (useRefs && nRef ? ' · tham chiếu ' + nRef + ' asset' : ''), 'acc'); }
