    const refNote = useRefs ? (refUsed ? ` · 🔗 ${refUsed} ảnh có tham chiếu` : (Object.keys(imgMap).length ? ' · ⚠️ 0 ảnh khớp tham chiếu (tag không trùng tên asset?)' : ' · (chưa có ảnh asset để tham chiếu)')) : '';
