// === L?: function _t2AudioDur ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=333c, shared=333c). Peer load SAU → ghi đè bản này. Sửa ở peer.
async function _t2AudioDur(file){
  try {
    const buf = await file.arrayBuffer();
    const ctx = new (window.AudioContext || window.webkitAudioContext)();
    const dec = await ctx.decodeAudioData(buf.slice(0));
    const s = dec.duration; try { ctx.close(); } catch (e) {}
    return s || 0;
  } catch (e) { return 0; }
}

