// === L?: function _splitCharNames ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=177c, shared=177c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function _splitCharNames(str){
  return String(str || '').split(/\s*(?:,|;|\/|&|\+|\band\b|\bvà\b|\bcùng\b)\s*/i).map(s => s.replace(/\[.*?\]/g, '').trim()).filter(Boolean);
}

// === L?: const _CROWD_RE ===
const _CROWD_RE = /^(crowd|crowds|people|persons?|bystanders?|passers?[- ]?by|onlookers?|audience|extras?|villagers?|workers?|colleagues?|co[- ]?workers?|staff|patients|doctors|nurses|guests|attendees|group|team|everyone|others?|strangers?|figures?|silhouettes?|men|women|children|kids|customers?|shoppers?|pedestrians?|soldiers?|students?|guards?|reporters?|crowd of .*)$/i;

// === L?: function _isCrowdName ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=170c, shared=170c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function _isCrowdName(n){ n = String(n || '').trim(); if (!n) return true; if (_CROWD_RE.test(n)) return true; if (n.split(/\s+/).length > 4) return true; return false; }

// === L?: function _isComboName ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=79c, shared=79c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function _isComboName(n){ return /[,;/&+]| and | và /i.test(String(n || '')); }

// === L?: const _T2_BG_MIN ===
const _T2_BG_MIN = 2;

// === L?: function _collectCastToAssets ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=2639c, shared=2639c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function _collectCastToAssets(){
  // Đếm số cảnh mỗi NHÂN VẬT RIÊNG xuất hiện (đã tách chuỗi ghép) → giữ MỌI nhân vật có tên (kể cả 1 lần), chỉ bỏ quần chúng + combo.
  const freq = {}; const bgFreq = {};
  for (const s of (state.scenes || [])) {
    const seen = new Set();
    for (const nm of _splitCharNames(s.character)) {
      if (_isCrowdName(nm)) continue;
      const k = nm.toLowerCase();
      if (!seen.has(k)) { seen.add(k); (freq[k] = freq[k] || { n: nm, c: 0 }).c++; }
    }
    const b = String(s.background || '').trim();
    if (b && !_isCrowdName(b)) (bgFreq[b.toLowerCase()] = bgFreq[b.toLowerCase()] || { n: b, c: 0 }).c++;
  }
  // GIỮ nơi chốn xương sống (≥2 cảnh); nơi dùng 1 lần → gỡ khỏi cảnh + bỏ ngoặc
  // trong prompt, nếu không tag sẽ trỏ vào asset không tồn tại (không có ảnh ref).
  const locSeen = Object.values(bgFreq).filter(x => x.c >= _T2_BG_MIN).map(x => x.n);
  const oneOff = new Set(Object.values(bgFreq).filter(x => x.c < _T2_BG_MIN).map(x => x.n.toLowerCase()));
  let dropped = 0;
  if (oneOff.size){
    for (const s of (state.scenes || [])){
      const b = String(s.background || '').trim();
      if (!b || !oneOff.has(b.toLowerCase())) continue;
      s.background = '';
      dropped++;
      ['scenePrompts', 'scenePrompts2'].forEach(key => {
        const cur = (state[key] || {})[s.id];
        if (!cur) return;
        // bỏ ngoặc, giữ nguyên chữ → prompt vẫn tả đúng nơi đó
        const re = new RegExp('\\[\\s*' + b.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\s*\\]', 'gi');
        state[key][s.id] = cur.replace(re, b);
      });
    }
    if (typeof novaLog === 'function') novaLog(`🏠 Bối cảnh: giữ ${locSeen.length} nơi lặp lại (≥${_T2_BG_MIN} cảnh), bỏ ${oneOff.size} nơi dùng 1 lần ở ${dropped} cảnh — tả thẳng trong prompt, khỏi tạo ảnh tham chiếu.`, 'ok');
  }
  const cast = Object.values(freq).filter(x => x.c >= 1).map(x => x.n);   // giữ MỌI nhân vật có tên (kể cả 1 lần) — theo web tool; chỉ quần chúng/combo bị loại (đã lọc ở trên)
  const strip = x => String(x).replace(/\s*\[.*?\]\s*$/, '').trim();
  const mergeUniq = (arr, add) => { const a = Array.isArray(arr) ? arr.slice() : []; const seen = new Set(a.map(strip)); add.forEach(x => { if (x && !seen.has(strip(x))) { a.push(x); seen.add(strip(x)); } }); return a; };
  const keepExisting = (state.charactersV || []).filter(n => !_isComboName(n) && !_isCrowdName(n));   // giữ nhân vật CÁ NHÂN đã có, bỏ combo cũ
  state.charactersV = mergeUniq(keepExisting, cast);
  state.backgroundsV = mergeUniq((state.backgroundsV || []).filter(n => !_isCrowdName(n)), locSeen);
}

// === L?: function t2MergeShortNow ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở tool-t2.js (peer=2220c, shared=2220c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function t2MergeShortNow(){
  if (!Array.isArray(state.scenes) || state.scenes.length < 2) return setStatus2('Chưa có cảnh để gộp.', 'error');
  const minS = parseInt(document.getElementById('minSecPerImg')?.value) || 3;
  const maxS = parseInt(document.getElementById('maxSecPerImg')?.value) || 6;
  const P = state.scenePrompts || {}, P2 = state.scenePrompts2 || {}, IMG = state.sceneImages || {}, IMGB = state.sceneImagesB || {}, VID = state.sceneVideos || {}, VEO = state.veoPrompts || {}, MOT = state.motionPrompts || {};
  const out = [], nP = {}, nP2 = {}, nIMG = {}, nIMGB = {}, nVID = {}, nVEO = {}, nMOT = {};
  let merged = 0;
  for (const s of state.scenes){
    const prev = out[out.length - 1];
    if (prev && (+s.duration || 0) < minS && ((+prev.duration || 0) + (+s.duration || 0)) <= maxS * 1.05 && s.text && !String(prev.text || '').includes(String(s.text).trim())){
      prev.text = (String(prev.text || '') + ' ' + s.text).trim();
      prev.duration = +((+prev.duration || 0) + (+s.duration || 0)).toFixed(1);
      merged++;   // dữ liệu của cảnh bị gộp bỏ đi, giữ prompt/ảnh của cảnh trước
    } else {
      const nid = String(out.length + 1).padStart(3, '0'); const old = s.id;
      out.push({ ...s, id: nid });
      if (P[old]) nP[nid] = P[old]; if (P2[old]) nP2[nid] = P2[old];
      if (IMG[old]) nIMG[nid] = IMG[old]; if (IMGB[old]) nIMGB[nid] = IMGB[old];
      if (VID[old]) nVID[nid] = VID[old]; if (VEO[old]) nVEO[nid] = VEO[old]; if (MOT[old]) nMOT[nid] = MOT[old];
    }
  }
  if (!merged) return setStatus2('✓ Không có cảnh nào ngắn hơn ' + minS + 's — khỏi gộp.', 'ok');
  state.scenes = out; state.scenePrompts = nP; state.scenePrompts2 = nP2;
  state.sceneImages = nIMG; state.sceneImagesB = nIMGB; state.sceneVideos = nVID; state.veoPrompts = nVEO; state.motionPrompts = nMOT;
  if (typeof renderAllT2 === 'function') renderAllT2(); else { if (typeof renderTable === 'function') renderTable(); if (typeof renderPromptsV === 'function') renderPromptsV(); }
  if (typeof renderVeoPrompts === 'function') renderVeoPrompts();
  saveState(true);
  setStatus2('🔗 Đã gộp ' + merged + ' cảnh ngắn (<' + minS + 's) → còn ' + out.length + ' cảnh.', 'ok');
}

// === L?: function t2SplitLongNow ===
