    const miss = (typeof _t2GenSceneMissCount === 'function') ? _t2GenSceneMissCount() : 0;
    setStatus2(miss ? ('🖼 Tạo ảnh cảnh xong · còn ' + miss + ' ảnh thiếu — bấm lại để tạo tiếp.') : '✓ Đã tạo đủ ảnh cảnh.', miss ? 'info' : 'ok');
