// === L?: function _renumberVideos ===
// ⚠️  DEDUP-DUPLICATE: hàm này cũng ở utility.js (peer=198c, shared=198c). Peer load SAU → ghi đè bản này. Sửa ở peer.
function _renumberVideos(p){
  if (!p || !Array.isArray(p.videos)) return;
  let n = 0;
  for (const v of p.videos){ n++; if (/^Video \d+$/.test(String(v.name || ''))) v.name = 'Video ' + n; }
}

